/**
 * Builds vendor/leonardo.mjs — the committed, pinned browser bundle of
 * @adobe/leonardo-contrast-colors that palette generation loads at runtime
 * (engine/generate.mjs), in Node and in the browser alike. Run with
 * `npm run vendor-leonardo` after bumping the pinned package, review the
 * bundle diff, and commit the result. See vendor/README.md.
 */
import fs from 'fs';
import { createRequire } from 'module';
import path from 'path';
import { fileURLToPath } from 'url';
import { build } from 'esbuild';

const require = createRequire(import.meta.url);
const VENDOR_DIR = path.dirname(fileURLToPath(import.meta.url));
// The package's exports map hides ./package.json — read it from the
// resolved entry module's directory instead.
const PACKAGE_DIR = path.dirname(require.resolve('@adobe/leonardo-contrast-colors'));
const { version, license } = JSON.parse(fs.readFileSync(path.join(PACKAGE_DIR, 'package.json'), 'utf-8'));

await build({
  stdin: {
    contents: "export * from '@adobe/leonardo-contrast-colors';",
    resolveDir: VENDOR_DIR,
  },
  bundle: true,
  format: 'esm',
  platform: 'browser',
  legalComments: 'inline',
  banner: {
    js: [
      '/**',
      ` * Vendored @adobe/leonardo-contrast-colors@${version} (${license}) with its`,
      ' * dependencies — a single-file ESM browser bundle. GENERATED by',
      ' * `npm run vendor-leonardo` (vendor/build.mjs); do not edit by hand.',
      ' * Provenance and refresh steps: vendor/README.md.',
      ' */',
    ].join('\n'),
  },
  outfile: path.join(VENDOR_DIR, 'leonardo.mjs'),
});

console.log(`Bundled @adobe/leonardo-contrast-colors@${version} into vendor/leonardo.mjs`);
